[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectRoot,[string]$RequestText,[switch]$Explicit,[switch]$SelfMaintenance,[string[]]$OnecScope,[string[]]$StandardScope,[object[]]$BoundaryEvidence)
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath($ProjectRoot);$bsl=@(Get-ChildItem $root -Filter *.bsl -Recurse -File -ErrorAction SilentlyContinue);$xml=@(Get-ChildItem $root -Filter *.xml -Recurse -File -ErrorAction SilentlyContinue|ForEach-Object{try{$x=[xml](Get-Content -Raw $_.FullName);if([string]$x.DocumentElement.NamespaceURI -match '^http://v8\.1c\.ru/'){$_}}catch{}});$v8=Test-Path (Join-Path $root 'v8project.yaml');$real=(($xml.Count -gt 0 -and $bsl.Count -gt 0)-or($v8 -and $bsl.Count));$class=if($Explicit){'explicit_user_request'}elseif($SelfMaintenance){'workflow_self_maintenance'}elseif($real){'confirmed_1c_evidence'}else{'not_applicable'};$one=@($OnecScope|Where-Object{$_}|ForEach-Object{$_ -replace '\\','/'}|Sort-Object -Unique);$std=@($StandardScope|Where-Object{$_}|ForEach-Object{$_ -replace '\\','/'}|Sort-Object -Unique);$overlap=@($one|Where-Object{$_ -in $std});if($overlap.Count){throw 'routing scope overlap'};[pscustomobject][ordered]@{applicable=($real-or$Explicit-or$SelfMaintenance);classification=$class;markers=@();onec_evidence=@($xml|ForEach-Object FullName);routing_manifest=[ordered]@{protocol_version=2;onec_scope=$one;standard_scope=$std;boundary_evidence=@($BoundaryEvidence);overlap=$overlap}}|ConvertTo-Json -Depth 12
